assert len(CANONICAL_SLOTS) == 1024, f"Expected 1024 slots, got {len(CANONICAL_SLOTS)}"
for i, slot in enumerate(CANONICAL_SLOTS):
    assert slot.index == i, f"Slot {slot.name} index mismatch: expected {i}, got {slot.index}"

SLOT_NAME_TO_INDEX: Dict[str, int] = {slot.name: slot.index for slot in CANONICAL_SLOTS}
SLOT_INDEX_TO_NAME: Dict[int, str] = {slot.index: slot.name for slot in CANONICAL_SLOTS}

# Backward compatibility aliases for historical or synonymous slot names
SLOT_ALIASES: Dict[str, str] = {
    "TOM_BELIEF_FIRST_ORDER": "TOM_FIRST_ORDER_BELIEF",
    "TOM_BELIEF_SECOND_ORDER": "TOM_SECOND_ORDER_BELIEF",
    "TOM_SHARED_ATTENTION": "TOM_JOINT_ATTENTION_FOCUS",
    "TOM_INTENTION": "PLAN_INTENDED_ACTION_STEP",
    "TOM_DESIRE": "DRIVE_CURIOSITY_EPISTEMIC",
    "ROLE_DECEPTIVE_PROJECTION": "INTENT_DECEPTIVE_PROJECTION",
    "ROLE_SARCASM_IRONY": "INTENT_IRONY_SARCASM",
}

for alias_k, target_v in list(SLOT_ALIASES.items()):
    if target_v in SLOT_NAME_TO_INDEX:
        SLOT_NAME_TO_INDEX[alias_k] = SLOT_NAME_TO_INDEX[target_v]


def get_slot_by_name(name: str) -> Optional[SlotDefinition]:
    """Retrieves slot definition by exact name (supporting legacy aliases)."""
    idx = SLOT_NAME_TO_INDEX.get(name)
    if idx is not None:
        return CANONICAL_SLOTS[idx]
    return None


def get_slot_by_index(index: int) -> SlotDefinition:
    """Retrieves slot definition by index [0, 1023]."""
    if not (0 <= index < 1024):
        raise IndexError(f"Slot index {index} out of range [0, 1023]")
    return CANONICAL_SLOTS[index]


def get_slot_names() -> List[str]:
    """Returns an ordered list of all 1024 canonical slot names."""
    return [slot.name for slot in CANONICAL_SLOTS]


# Expose all 1024 slot definitions as module-level immutable integer constants
for _slot in CANONICAL_SLOTS:
    globals()[_slot.name] = _slot.index

# Expose legacy aliases at module level
for alias_k, target_v in SLOT_ALIASES.items():
    if target_v in SLOT_NAME_TO_INDEX:
        globals()[alias_k] = SLOT_NAME_TO_INDEX[target_v]


def export_canonical_slots_layout(output_path: Union[str, Path] = "output/canonical_slots_layout.json") -> Path:
    """Exports the 1024 canonical slot definitions to a JSON file."""
    p = Path(output_path)
    p.parent.mkdir(parents=True, exist_ok=True)
    slots_layout = [
        {
            "index": s.index,
            "name": s.name,
            "band_id": int(s.band),
            "band_name": s.band.name,
            "category": s.category,
            "description": s.description,
        }
        for s in CANONICAL_SLOTS
    ]
    with open(p, "w", encoding="utf-8") as f:
        json.dump(slots_layout, f, indent=2)
    return p


__all__ = [
    "SlotBand",
    "SlotDefinition",
    "BAND_0_SLOTS",
    "BAND_1_SLOTS",
    "BAND_2_SLOTS",
    "BAND_3_SLOTS",
    "BAND_4_SLOTS",
    "BAND_5_SLOTS",
    "BAND_6_SLOTS",
    "BAND_7_SLOTS",
    "CANONICAL_SLOTS",
    "SLOT_NAME_TO_INDEX",
    "SLOT_INDEX_TO_NAME",
    "SLOT_ALIASES",
    "get_slot_by_name",
    "get_slot_by_index",
    "get_slot_names",
    "export_canonical_slots_layout",
] + [slot.name for slot in CANONICAL_SLOTS] + list(SLOT_ALIASES.keys())
